def what_notes_undid(apps, schema_editor):
    """
    What the debit notes posted before undid of each discount, newest first over what was not withdrawn, as they
    undo from here (settlement.undo_discounts, O600). Each note booked the whole beside the newest discount
    then: where the discounts it undid were booked to more than one account, the books may hold the split O600
    names, and the bill is reported; so is one whose notes undid more than its discounts hold.
    """
    Document = apps.get_model("purchasing", "Bill")
    Discount = apps.get_model("purchasing", "BillDiscount")
    JournalLine = apps.get_model("accounting", "JournalLine")
    for document in Document.objects.filter(discounts__isnull=False).distinct().order_by("pk"):
        undone = sum((note.reversed_discount for note in Document.objects.filter(debits=document, posted=True)),
                     Decimal("0"))
        left, accounts = undone, set()
        for row in Discount.objects.filter(bill=document).order_by("-date", "-pk"):
            here = min(row.amount - row.withdrawn_amount, left)
            if here <= 0:
                continue
            Discount.objects.filter(pk=row.pk).update(undone_amount=here)
            accounts |= set(JournalLine.objects.filter(entry_id=row.journal_entry_id)
                            .exclude(account_id=document.payable_account_id).values_list("account__code", flat=True))
            left -= here
        name = document.number or document.pk
        if left > 0:
            print(f"purchasing 0095: {name}'s debit notes undid {undone} of its settlement discounts, {left} more "
                  "than they hold after withdrawals; it is set on none. Read its discounts and notes.")
        if len(accounts) > 1:
            print(f"purchasing 0095: {name}'s debit notes undid discounts booked to {', '.join(sorted(accounts))}, "
                  "and each booked what it undid beside the newest: those accounts may hold the difference (O600).")


